<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\User;use App\Features\Stock\Models\Stock;use App\Features\Stock\Enums\StockStatus;
class StockWorkflowTest extends TestCase {use RefreshDatabase;public function test_authenticated_member_can_view_own_stocks():void{$u=User::create(['name'=>'Member','username'=>'member1','password'=>'password','role'=>'member']);Stock::create(['user_id'=>$u->id,'name'=>'Mouse','quantity'=>4,'unit'=>'pcs','min_stock'=>5,'status'=>StockStatus::LowStock]);$this->actingAs($u)->get('/stocks')->assertOk()->assertSee('Mouse');}public function test_member_cannot_open_another_members_stock():void{$a=User::create(['name'=>'A','username'=>'a','password'=>'password','role'=>'member']);$b=User::create(['name'=>'B','username'=>'b','password'=>'password','role'=>'member']);$stock=Stock::create(['user_id'=>$b->id,'name'=>'Private','quantity'=>1,'unit'=>'pcs','min_stock'=>2,'status'=>StockStatus::LowStock]);$this->actingAs($a)->get('/stocks/'.$stock->id)->assertNotFound();}public function test_guest_is_redirected_to_login():void{$this->get('/stocks')->assertRedirect('/login');}}
